-- Roam: apply all migrations to an EMPTY Supabase database.-- Dashboard -> SQL Editor -> New query -> paste entire file -> Run-- Regenerated by: pnpm supabase:bundle (45 files)

-- ========== 20240001000000_create_tables.sql ==========
-- Migration 001: Create all tables (Roam Choreography V1)
-- Tables created in dependency order.

-- 1. users — links to Supabase Auth
CREATE TABLE users (
  id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  email text NOT NULL,
  plan text NOT NULL DEFAULT 'free' CHECK (plan IN ('free', 'creator', 'pro', 'studio')),
  created_at timestamptz DEFAULT now()
);

-- 2. sessions — FK to users
CREATE TABLE sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name text NOT NULL,
  created_at timestamptz DEFAULT now()
);

-- 3. music_tracks — FK to sessions
CREATE TABLE music_tracks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  source_type text NOT NULL CHECK (source_type IN ('upload', 'youtube')),
  source_url text,
  storage_path text,
  bpm float,
  beat_grid jsonb,
  sections jsonb DEFAULT '[]',
  analysis_status text DEFAULT 'pending' CHECK (analysis_status IN ('pending', 'processing', 'complete', 'failed')),
  created_at timestamptz DEFAULT now()
);

-- 4. clips — FK to sessions
CREATE TABLE clips (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  local_id uuid NOT NULL,
  label text NOT NULL DEFAULT 'Clip',
  mux_upload_id text,
  mux_asset_id text UNIQUE,
  mux_playback_id text,
  mux_passthrough jsonb,
  upload_status text NOT NULL DEFAULT 'local' CHECK (upload_status IN ('local', 'queued', 'uploading', 'processing', 'ready', 'failed')),
  move_name text,
  style text,
  energy text,
  difficulty text,
  bpm integer,
  notes text,
  recorded_at timestamptz NOT NULL,
  created_at timestamptz DEFAULT now(),
  UNIQUE (session_id, local_id)
);

-- 5. analysis_jobs — FKs to sessions and music_tracks
CREATE TABLE analysis_jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  music_track_id uuid NOT NULL REFERENCES music_tracks(id) ON DELETE CASCADE,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'complete', 'failed')),
  attempt_count integer NOT NULL DEFAULT 0,
  created_at timestamptz DEFAULT now(),
  claimed_at timestamptz,
  lease_expires_at timestamptz,
  completed_at timestamptz,
  timeout_at timestamptz,
  error text
);

-- 7. claim_analysis_job RPC: atomically claim a single pending job
create or replace function claim_analysis_job()
returns setof analysis_jobs
language sql
as $$
  update analysis_jobs
  set
    status = 'processing',
    claimed_at = now(),
    lease_expires_at = now() + interval '60 seconds'
  where id = (
    select id
    from analysis_jobs
    where status = 'pending'
    and (timeout_at is null or timeout_at > now())
    order by created_at
    for update skip locked
    limit 1
  )
  returning *;
$$;

-- 6. share_tokens — FK to sessions
CREATE TABLE share_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  token uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
  created_at timestamptz DEFAULT now(),
  revoked_at timestamptz
);

-- ========== 20240002000000_create_indexes.sql ==========
-- Migration 002: Create indexes (Roam Choreography V1)

CREATE INDEX ON share_tokens(token);

CREATE INDEX ON clips(session_id, upload_status);

CREATE INDEX ON clips(session_id, recorded_at DESC);

CREATE INDEX ON analysis_jobs(status, timeout_at);

-- ========== 20240003000000_rls_policies.sql ==========
-- Migration 003: Enable RLS and create policies (Roam Choreography V1)

ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE music_tracks ENABLE ROW LEVEL SECURITY;
ALTER TABLE clips ENABLE ROW LEVEL SECURITY;
ALTER TABLE analysis_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE share_tokens ENABLE ROW LEVEL SECURITY;

-- users: own row only
CREATE POLICY users_select_own ON users FOR SELECT USING (id = auth.uid());
CREATE POLICY users_update_own ON users FOR UPDATE USING (id = auth.uid());

-- sessions: all operations for own sessions
CREATE POLICY sessions_all_own ON sessions FOR ALL USING (user_id = auth.uid());

-- music_tracks: all operations where session belongs to user
CREATE POLICY music_tracks_all_own_session ON music_tracks FOR ALL
  USING (session_id IN (SELECT id FROM sessions WHERE user_id = auth.uid()));

-- clips: all operations where session belongs to user
CREATE POLICY clips_all_own_session ON clips FOR ALL
  USING (session_id IN (SELECT id FROM sessions WHERE user_id = auth.uid()));

-- analysis_jobs: API (authenticated) can INSERT jobs for own sessions; service_role has explicit full access
CREATE POLICY analysis_jobs_insert_own_session ON analysis_jobs FOR INSERT
  TO authenticated
  WITH CHECK (session_id IN (SELECT id FROM sessions WHERE user_id = auth.uid()));
CREATE POLICY analysis_jobs_service_role_all ON analysis_jobs FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- share_tokens: owner can SELECT/INSERT/UPDATE/DELETE; anon SELECT for token-scoped non-revoked access
CREATE POLICY share_tokens_select_anon ON share_tokens FOR SELECT
  TO anon
  USING (
    revoked_at IS NULL
    AND token = NULLIF(trim(current_setting('app.requested_share_token', true)), '')::uuid
  );
CREATE POLICY share_tokens_select_own_session ON share_tokens FOR SELECT
  USING (session_id IN (SELECT id FROM sessions WHERE user_id = auth.uid()));
CREATE POLICY share_tokens_insert_own_session ON share_tokens FOR INSERT
  WITH CHECK (session_id IN (SELECT id FROM sessions WHERE user_id = auth.uid()));
CREATE POLICY share_tokens_update_own_session ON share_tokens FOR UPDATE
  USING (session_id IN (SELECT id FROM sessions WHERE user_id = auth.uid()));
CREATE POLICY share_tokens_delete_own_session ON share_tokens FOR DELETE
  USING (session_id IN (SELECT id FROM sessions WHERE user_id = auth.uid()));

-- ========== 20240004000000_get_shared_session_rpc.sql ==========
-- Migration 004: get_shared_session RPC (anon-accessible share page)

CREATE OR REPLACE FUNCTION get_shared_session(p_token uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_session_id uuid;
  v_session sessions%ROWTYPE;
  v_music_track music_tracks%ROWTYPE;
  v_clips jsonb;
BEGIN
  -- Look up valid share token
  SELECT st.session_id INTO v_session_id
  FROM share_tokens st
  WHERE st.token = p_token AND st.revoked_at IS NULL AND st.clip_id IS NULL;

  IF v_session_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Fetch session
  SELECT * INTO v_session FROM sessions WHERE id = v_session_id;

  -- Fetch single music_track (V1: one track per session)
  SELECT * INTO v_music_track
  FROM music_tracks
  WHERE session_id = v_session_id
  LIMIT 1;

  -- Fetch clips with upload_status IN ('ready', 'processing'), ordered by recorded_at ASC
  SELECT COALESCE(
    (SELECT jsonb_agg(to_jsonb(cl) ORDER BY cl.recorded_at ASC)
     FROM clips cl
     WHERE cl.session_id = v_session_id AND cl.upload_status IN ('ready', 'processing')),
    '[]'::jsonb
  ) INTO v_clips;

  RETURN json_build_object(
    'session', to_jsonb(v_session),
    'music_track', CASE WHEN v_music_track.id IS NULL THEN NULL ELSE to_jsonb(v_music_track) END,
    'clips', COALESCE(v_clips, '[]'::jsonb)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION get_shared_session(uuid) TO anon;

