-- ========== 20240007000000_fix_claim_analysis_job.sql ==========
-- Migration 007: Fix claim_analysis_job for already-migrated environments
-- Ensures no claim-time attempt_count increment and timeout_at validity guard.
-- Historical migration 001 is unchanged; this migration rolls out the fix.

create or replace function claim_analysis_job()
returns setof analysis_jobs
language sql
as $$
  update analysis_jobs
  set
    status = 'processing',
    claimed_at = now(),
    lease_expires_at = now() + interval '60 seconds'
  where id = (
    select id
    from analysis_jobs
    where status = 'pending'
    and (timeout_at is null or timeout_at > now())
    order by created_at
    for update skip locked
    limit 1
  )
  returning *;
$$;

-- ========== 20240008000000_claim_sets_timeout_at.sql ==========
-- Migration 008: Extend claim_analysis_job to set timeout_at at claim time
-- Ensures every claimed job has a valid, non-NULL timeout_at for the analyzer
-- and eliminates KeyError on job["timeout_at"] in main.py.

create or replace function claim_analysis_job()
returns setof analysis_jobs
language sql
as $$
  update analysis_jobs
  set
    status = 'processing',
    claimed_at = now(),
    lease_expires_at = now() + interval '60 seconds',
    timeout_at = now() + interval '5 minutes'
  where id = (
    select id
    from analysis_jobs
    where status = 'pending'
    and (timeout_at is null or timeout_at > now())
    order by created_at
    for update skip locked
    limit 1
  )
  returning *;
$$;

-- ========== 20240009000000_claim_sets_timeout_at_when_null.sql ==========
-- Migration 009: Fix claim_analysis_job for already-migrated databases
-- Sets timeout_at only when null (no overwrite). Keeps same atomic claim and
-- timeout guard behavior. Historical 008 unchanged; this migration ensures
-- production and other upgraded databases receive the runtime fix.

create or replace function claim_analysis_job()
returns setof analysis_jobs
language sql
as $$
  update analysis_jobs
  set
    status = 'processing',
    claimed_at = now(),
    lease_expires_at = now() + interval '60 seconds',
    timeout_at = coalesce(timeout_at, now() + interval '5 minutes')
  where id = (
    select id
    from analysis_jobs
    where status = 'pending'
    and (timeout_at is null or timeout_at > now())
    order by created_at
    for update skip locked
    limit 1
  )
  returning *;
$$;

