-- ========== 20240016000000_update_clip_tags_with_history_rpc.sql ==========
-- RPC for atomic tag update: snapshot history + update clips in one transaction.
-- Ensures version-history row is created before applying tag updates.

CREATE OR REPLACE FUNCTION update_clip_tags_with_history(
  p_clip_id uuid,
  p_user_id uuid,
  p_snapshot jsonb,
  p_updates jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_clip_ok boolean;
  v_updated jsonb;
BEGIN
  -- 1. Verify clip belongs to user via session
  SELECT EXISTS(
    SELECT 1 FROM clips c
    INNER JOIN sessions s ON c.session_id = s.id
    WHERE c.id = p_clip_id AND s.user_id = p_user_id
  ) INTO v_clip_ok;
  IF NOT v_clip_ok THEN
    RAISE EXCEPTION 'Clip not found or access denied' USING errcode = 'P0001';
  END IF;

  -- 2. Insert history snapshot first (must succeed before any update)
  INSERT INTO clip_tag_history (clip_id, snapshot, saved_by)
  VALUES (p_clip_id, p_snapshot, p_user_id);

  -- 3. Apply updates to clips (only fields present in p_updates)
  UPDATE clips
  SET
    move_name = CASE WHEN p_updates ? 'move_name' THEN (p_updates->>'move_name')::text ELSE move_name END,
    style = CASE WHEN p_updates ? 'style' THEN (p_updates->>'style')::text ELSE style END,
    energy = CASE WHEN p_updates ? 'energy' THEN (p_updates->>'energy')::text ELSE energy END,
    difficulty = CASE WHEN p_updates ? 'difficulty' THEN (p_updates->>'difficulty')::text ELSE difficulty END,
    bpm = CASE WHEN p_updates ? 'bpm' THEN (p_updates->'bpm')::integer ELSE bpm END,
    notes = CASE WHEN p_updates ? 'notes' THEN (p_updates->>'notes')::text ELSE notes END
  WHERE id = p_clip_id;

  -- 4. Return updated clip as jsonb
  SELECT to_jsonb(cl) INTO v_updated
  FROM clips cl
  WHERE cl.id = p_clip_id;

  RETURN v_updated;
END;
$$;

-- ========== 20240017000000_replace_section_clips_rpc.sql ==========
-- RPC for atomic assembly replace: delete + insert in one transaction.
-- Validates session ownership and clip_ids before mutating state.

CREATE OR REPLACE FUNCTION replace_section_clips(
  p_session_id uuid,
  p_user_id uuid,
  p_assignments jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_session_ok boolean;
  v_clip_ids uuid[];
  v_clip_count int;
  v_valid_count int;
  v_a jsonb;
  v_result jsonb;
BEGIN
  -- 1. Verify session belongs to user
  SELECT EXISTS(
    SELECT 1 FROM sessions WHERE id = p_session_id AND user_id = p_user_id
  ) INTO v_session_ok;
  IF NOT v_session_ok THEN
    RAISE EXCEPTION 'Session not found or access denied' USING errcode = 'P0001';
  END IF;

  -- 2. Validate payload: must be array of objects with section_label, section_start_ms, clip_id, position
  IF jsonb_typeof(p_assignments) != 'array' THEN
    RAISE EXCEPTION 'assignments must be an array' USING errcode = 'P0002';
  END IF;

  -- 3. Extract and validate clip_ids exist and belong to session
  FOR v_a IN SELECT * FROM jsonb_array_elements(p_assignments)
  LOOP
    IF v_a->>'clip_id' IS NULL OR v_a->>'section_label' IS NULL
       OR (v_a->'section_start_ms') IS NULL OR (v_a->'position') IS NULL THEN
      RAISE EXCEPTION 'Each assignment must have section_label, section_start_ms, clip_id, position'
        USING errcode = 'P0002';
    END IF;
  END LOOP;

  SELECT COALESCE(array_agg((elem->>'clip_id')::uuid), ARRAY[]::uuid[])
  INTO v_clip_ids
  FROM jsonb_array_elements(p_assignments) AS elem
  WHERE elem->>'clip_id' IS NOT NULL AND elem->>'clip_id' != '';

  SELECT COUNT(*) INTO v_valid_count
  FROM clips c
  WHERE c.id = ANY(v_clip_ids) AND c.session_id = p_session_id;

  SELECT array_length(v_clip_ids, 1) INTO v_clip_count;
  IF v_clip_count IS NULL THEN
    v_clip_count := 0;
  END IF;
  IF v_valid_count != v_clip_count THEN
    RAISE EXCEPTION 'One or more clip_ids are invalid or do not belong to this session'
      USING errcode = 'P0002';
  END IF;

  -- 4. Delete existing + insert new (atomic in one transaction)
  DELETE FROM section_clips WHERE session_id = p_session_id;

  IF v_clip_count > 0 THEN
    INSERT INTO section_clips (session_id, section_label, section_start_ms, clip_id, position)
    SELECT
      p_session_id,
      elem->>'section_label',
      (elem->'section_start_ms')::int,
      (elem->>'clip_id')::uuid,
      (elem->'position')::int
    FROM jsonb_array_elements(p_assignments) AS elem;
  END IF;

  -- 5. Return inserted rows as jsonb array
  SELECT COALESCE(
    (SELECT jsonb_agg(to_jsonb(sc) ORDER BY sc.section_start_ms, sc.position)
     FROM section_clips sc WHERE sc.session_id = p_session_id),
    '[]'::jsonb
  ) INTO v_result;

  RETURN v_result;
END;
$$;

-- ========== 20240018000000_rls_feedback_uniqueness.sql ==========
-- RLS: Remove permissive anon policies; add token-scoped RPCs for comments and feedback.
-- Feedback: Deduplicate and enforce UNIQUE(clip_id) on feedback_requests.

-- 1. Drop permissive anon SELECT policies
DROP POLICY IF EXISTS clip_comments_select_anon ON clip_comments;
DROP POLICY IF EXISTS feedback_requests_select_anon_open ON feedback_requests;

-- 2. RPC: Get clip comments for a valid share token (anon-accessible)
CREATE OR REPLACE FUNCTION get_clip_comments_for_share(p_token uuid, p_clip_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_session_id uuid;
  v_clip_ok boolean;
  v_result jsonb;
BEGIN
  SELECT st.session_id INTO v_session_id
  FROM share_tokens st
  WHERE st.token = p_token AND st.revoked_at IS NULL;

  IF v_session_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM clips c
    WHERE c.id = p_clip_id AND c.session_id = v_session_id
  ) INTO v_clip_ok;

  IF NOT v_clip_ok THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT COALESCE(
    (SELECT jsonb_agg(to_jsonb(cc) ORDER BY cc.timecode_ms)
     FROM clip_comments cc
     WHERE cc.clip_id = p_clip_id AND cc.session_id = v_session_id),
    '[]'::jsonb
  ) INTO v_result;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION get_clip_comments_for_share(uuid, uuid) TO anon;

-- 3. RPC: Get feedback request status for a valid share token (anon-accessible)
CREATE OR REPLACE FUNCTION get_feedback_request_for_share(p_token uuid, p_clip_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_session_id uuid;
  v_clip_ok boolean;
  v_result jsonb;
BEGIN
  SELECT st.session_id INTO v_session_id
  FROM share_tokens st
  WHERE st.token = p_token AND st.revoked_at IS NULL;

  IF v_session_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT EXISTS(
    SELECT 1 FROM clips c
    WHERE c.id = p_clip_id AND c.session_id = v_session_id
  ) INTO v_clip_ok;

  IF NOT v_clip_ok THEN
    RETURN NULL;
  END IF;

  SELECT to_jsonb(fr) INTO v_result
  FROM feedback_requests fr
  WHERE fr.clip_id = p_clip_id AND fr.session_id = v_session_id
  LIMIT 1;

  RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION get_feedback_request_for_share(uuid, uuid) TO anon;

-- 4. Deduplicate feedback_requests: keep one row per clip_id (prefer open, then most recent)
DELETE FROM feedback_requests
WHERE id NOT IN (
  SELECT DISTINCT ON (clip_id) id
  FROM feedback_requests
  ORDER BY clip_id, CASE status WHEN 'open' THEN 0 ELSE 1 END, created_at DESC NULLS LAST
);

-- 5. Add UNIQUE constraint on feedback_requests.clip_id (idempotent)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint c
    JOIN pg_class t ON c.conrelid = t.oid
    WHERE t.relname = 'feedback_requests' AND c.conname IN ('feedback_requests_clip_id_unique', 'feedback_requests_clip_id_key')
  ) THEN
    ALTER TABLE feedback_requests ADD CONSTRAINT feedback_requests_clip_id_unique UNIQUE (clip_id);
  END IF;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- ========== 20240019000000_rpc_security_hardening.sql ==========
-- RPC Security Hardening: Lock mutating SECURITY DEFINER functions to service_role only
--
-- These are mutating SECURITY DEFINER RPCs that must only be callable via the service-role
-- path (i.e., the apps/api server). Direct RPC calls from anon or authenticated roles
-- are blocked at the permission level.
--
-- The API routes apps/api/src/routes/assembly.ts and apps/api/src/routes/tags.ts already
-- use the service-role client (apps/api/src/lib/supabase.ts), so no API changes are needed.
-- After this migration, anon/authenticated direct RPC calls will receive permission denied.

-- update_clip_tags_with_history(uuid, uuid, jsonb, jsonb)
REVOKE EXECUTE ON FUNCTION update_clip_tags_with_history(uuid, uuid, jsonb, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION update_clip_tags_with_history(uuid, uuid, jsonb, jsonb) FROM anon;
REVOKE EXECUTE ON FUNCTION update_clip_tags_with_history(uuid, uuid, jsonb, jsonb) FROM authenticated;
GRANT EXECUTE ON FUNCTION update_clip_tags_with_history(uuid, uuid, jsonb, jsonb) TO service_role;

-- replace_section_clips(uuid, uuid, jsonb)
REVOKE EXECUTE ON FUNCTION replace_section_clips(uuid, uuid, jsonb) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION replace_section_clips(uuid, uuid, jsonb) FROM anon;
REVOKE EXECUTE ON FUNCTION replace_section_clips(uuid, uuid, jsonb) FROM authenticated;
GRANT EXECUTE ON FUNCTION replace_section_clips(uuid, uuid, jsonb) TO service_role;

