  WHERE clip_id IS NOT NULL AND revoked_at IS NULL;

-- ========== 20260319000003_get_shared_clip_rpc.sql ==========
-- Migration 20260319000003: get_shared_clip RPC (anon-accessible clip share page)

CREATE OR REPLACE FUNCTION get_shared_clip(p_token uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_session_id uuid;
  v_clip_id uuid;
  v_session sessions%ROWTYPE;
  v_clip clips%ROWTYPE;
BEGIN
  -- Look up valid clip-level share token (clip_id must be present)
  SELECT st.session_id, st.clip_id INTO v_session_id, v_clip_id
  FROM share_tokens st
  WHERE st.token = p_token AND st.revoked_at IS NULL AND st.clip_id IS NOT NULL;

  IF v_session_id IS NULL OR v_clip_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Fetch session (for display context)
  SELECT * INTO v_session FROM sessions WHERE id = v_session_id;

  -- Fetch the bound clip (scoped to session as defense-in-depth)
  SELECT * INTO v_clip FROM clips WHERE id = v_clip_id AND session_id = v_session_id;

  IF v_clip.id IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN json_build_object(
    'session', to_jsonb(v_session),
    'clip', to_jsonb(v_clip)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION get_shared_clip(uuid) TO anon;

-- ========== 20260319000004_get_shared_session_rpc_session_scope.sql ==========
-- Migration 20260319000004: tighten get_shared_session token scope (session-only tokens)

CREATE OR REPLACE FUNCTION get_shared_session(p_token uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_session_id uuid;
  v_session sessions%ROWTYPE;
  v_music_track music_tracks%ROWTYPE;
  v_clips jsonb;
BEGIN
  -- Look up valid *session-level* share token (clip_id must be NULL)
  SELECT st.session_id INTO v_session_id
  FROM share_tokens st
  WHERE st.token = p_token AND st.revoked_at IS NULL AND st.clip_id IS NULL;

  IF v_session_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Fetch session
  SELECT * INTO v_session FROM sessions WHERE id = v_session_id;

  -- Fetch single music_track (V1: one track per session)
  SELECT * INTO v_music_track
  FROM music_tracks
  WHERE session_id = v_session_id
  LIMIT 1;

  -- Fetch clips with upload_status IN ('ready', 'processing'), ordered by recorded_at ASC
  SELECT COALESCE(
    (SELECT jsonb_agg(to_jsonb(cl) ORDER BY cl.recorded_at ASC)
     FROM clips cl
     WHERE cl.session_id = v_session_id AND cl.upload_status IN ('ready', 'processing')),
    '[]'::jsonb
  ) INTO v_clips;

  RETURN json_build_object(
    'session', to_jsonb(v_session),
    'music_track', CASE WHEN v_music_track.id IS NULL THEN NULL ELSE to_jsonb(v_music_track) END,
    'clips', COALESCE(v_clips, '[]'::jsonb)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION get_shared_session(uuid) TO anon;

