  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions(id) on delete cascade,
  clip_id uuid not null references public.clips(id) on delete cascade,
  user_id uuid not null references auth.users(id),
  statement text,
  questions text,
  observations text,
  opinions text,
  created_at timestamptz not null default now()
);

alter table public.structured_feedback enable row level security;

create policy structured_feedback_insert_participants
  on public.structured_feedback
  for insert
  to authenticated
  with check (public.is_session_member(session_id));

create policy structured_feedback_select_owner
  on public.structured_feedback
  for select
  to authenticated
  using (
    session_id in (
      select id
      from public.sessions
      where user_id = auth.uid()
    )
  );

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'clips_id_session_id_key'
      and conrelid = 'public.clips'::regclass
  ) then
    alter table public.clips
      add constraint clips_id_session_id_key unique (id, session_id);
  end if;
end $$;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'structured_feedback_clip_session_fk'
      and conrelid = 'public.structured_feedback'::regclass
  ) then
    alter table public.structured_feedback
      add constraint structured_feedback_clip_session_fk
      foreign key (clip_id, session_id)
      references public.clips(id, session_id)
      on delete cascade;
  end if;
end $$;

-- ========== 20260418000000_drill_sequences.sql ==========
create table if not exists public.drill_sequences (
  session_id uuid primary key references public.sessions(id) on delete cascade,
  items jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

alter table public.drill_sequences enable row level security;

drop policy if exists "drill_sequences_select_owner_or_participant" on public.drill_sequences;
create policy "drill_sequences_select_owner_or_participant"
on public.drill_sequences
for select
using (
  exists (
    select 1
    from public.sessions s
    where s.id = drill_sequences.session_id
      and s.user_id = auth.uid()
  )
  or exists (
    select 1
    from public.group_participants gp
    where gp.session_id = drill_sequences.session_id
      and gp.user_id = auth.uid()
  )
);

drop policy if exists "drill_sequences_modify_owner_only" on public.drill_sequences;
create policy "drill_sequences_modify_owner_only"
on public.drill_sequences
for all
using (
  exists (
    select 1
    from public.sessions s
    where s.id = drill_sequences.session_id
      and s.user_id = auth.uid()
  )
)
with check (
  exists (
    select 1
    from public.sessions s
    where s.id = drill_sequences.session_id
      and s.user_id = auth.uid()
  )
);

-- ========== 20260419000000_moments_last_modified_at.sql ==========
ALTER TABLE moments
ADD COLUMN IF NOT EXISTS last_modified_at timestamptz DEFAULT now();

CREATE OR REPLACE FUNCTION set_moments_last_modified_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.last_modified_at = now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS moments_set_last_modified_at ON moments;

CREATE TRIGGER moments_set_last_modified_at
BEFORE UPDATE ON moments
FOR EACH ROW
EXECUTE FUNCTION set_moments_last_modified_at();

-- ========== 20260519000000_clip_marking_fingerprints.sql ==========
-- Marking search: compact motion fingerprints per clip (choreography similarity).

CREATE TABLE IF NOT EXISTS clip_marking_fingerprints (
  clip_id uuid PRIMARY KEY REFERENCES clips(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  fingerprint jsonb NOT NULL,
  dims integer NOT NULL,
  source text NOT NULL DEFAULT 'mux_thumbnails',
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS clip_marking_fingerprints_user_id_idx
  ON clip_marking_fingerprints (user_id);

ALTER TABLE clip_marking_fingerprints ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS clip_marking_fingerprints_own ON clip_marking_fingerprints;

CREATE POLICY clip_marking_fingerprints_own ON clip_marking_fingerprints
  FOR ALL
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());
